INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Unittests nur für große Projekte nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Module profitieren"}, {"text": "Ja", "correct": false, "because": "Qualität immer wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Unittests?', 3, '[{"text": "Funktionalität prüfen", "correct": true, "because": "Isolierte Module testen"}, {"text": "Performance messen", "correct": false, "because": "Anderer Fokus"}, {"text": "UI verbessern", "correct": false, "because": "Kein Design-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools eignen sich für Unittests?', 5, '[{"text": "JUnit", "correct": true, "because": "Für Java geeignet"}, {"text": "PyTest", "correct": true, "because": "Für Python ideal"}, {"text": "JMeter", "correct": false, "because": "Lasttests"}, {"text": "Selenium", "correct": false, "because": "UI-Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unittests prüfen Einzelmodule. b) Sie ersetzen Integrationstests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Integration separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Unittests?', 4, '[{"text": "Testabdeckung", "correct": false, "because": "Wichtig für Qualität"}, {"text": "Fehlerfälle", "correct": false, "because": "Müssen geprüft werden"}, {"text": "Farbschema", "correct": true, "because": "Kein Testfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Unittests immer manuell geschrieben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Tools automatisieren"}, {"text": "Ja", "correct": false, "because": "Automatisierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für Java-Unittests?', 3, '[{"text": "JUnit", "correct": true, "because": "Standard für Java"}, {"text": "PyTest", "correct": false, "because": "Für Python"}, {"text": "Postman", "correct": false, "because": "API-Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei Unittests wichtig?', 5, '[{"text": "Isolation", "correct": true, "because": "Module einzeln prüfen"}, {"text": "Automatisierung", "correct": true, "because": "Effizienz steigern"}, {"text": "Laufzeit", "correct": false, "because": "Performance-Fokus"}, {"text": "UI-Design", "correct": false, "because": "Kein Testziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Unittests finden Fehler früh. b) Sie machen Code schneller. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit nicht Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Unittests?', 4, '[{"text": "Testfälle", "correct": false, "because": "Grundlage der Tests"}, {"text": "Assertions", "correct": false, "because": "Ergebnisse prüfen"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Kein Testfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Unittests ohne Tools möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Manuell machbar"}, {"text": "Nein", "correct": false, "because": "Tools nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften fördern Unittests?', 4, '[{"text": "Code-Qualität", "correct": true, "because": "Fehler früh erkennen"}, {"text": "Wartbarkeit", "correct": true, "because": "Änderungen prüfbar"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Performance-Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Unittests nur für Entwickler sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch QA profitiert"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Unittests?', 3, '[{"text": "Testabdeckung", "correct": true, "because": "Vollständigkeit prüfen"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Viele Tests", "correct": false, "because": "Relevanz entscheidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PyTest ist für Python. b) Es ersetzt JUnit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "JUnit für Java"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Unittests?', 5, '[{"text": "Frühe Fehlererkennung", "correct": true, "because": "Vor Integration"}, {"text": "Regressionstests", "correct": true, "because": "Änderungen prüfen"}, {"text": "Schnellere Builds", "correct": false, "because": "Kein Build-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Unittests unwichtig?', 3, '[{"text": "Testfälle", "correct": false, "because": "Kern der Tests"}, {"text": "Isolation", "correct": false, "because": "Unabhängigkeit nötig"}, {"text": "UI-Layout", "correct": true, "because": "Kein Testaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Unittests manuelle Tests?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen, nicht ersetzen"}, {"text": "Ja", "correct": false, "because": "Manuelle Tests bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Unittests Refactoring erleichtern?', 2, '[{"text": "Ja", "correct": true, "because": "Änderungen prüfbar"}, {"text": "Nein", "correct": false, "because": "Sicherheit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist bei Unittest-Tools entscheidend?', 4, '[{"text": "Assertions", "correct": true, "because": "Ergebnisse validieren"}, {"text": "UI-Integration", "correct": false, "because": "Kein Fokus"}, {"text": "Lastsimulation", "correct": false, "because": "Performance-Tests"}]');
